{
   $count = 0;
   $format = array("B","KB","MB","GB","TB","PB","EB","ZB","YB");
   while(($size/1024)>1 && $count<8)
   {
       $size=$size/1024;
       $count++;
   }
   if( $size < 10 ) $decimals = 1;
   else $decimals = 0;
   $return = number_format($size,$decimals,'.',' ')." ".$format[$count];
