	if($rs_cnt){

		// Incremento e lettura versione elenco JSON
		$sql = "UPDATE co_distribuzione_counter_mobile SET versione = versione + 1 WHERE id = 1";
		if(!mysql_query($sql)){ ## Gestione errori ##
			avviso_admin('[QUERY - UPDATE]<br />Errore aggiornamento versione JSON<br /><br /><strong>QUERY:</strong> '.$sql.'<br /><strong>ERRORE:</strong> '.mysql_error());
			avviso_utente($messaggio_errore_utente, 'n');
