		$rs_vj = mysql_fetch_object($result_vj);

		// Contenuto JSON (solo versione)
		$json_content_versione = '{"version":'.$rs_vj->versione.'}';

		// Contenuto JSON (elenco)
		$json_content = '{';
			$json_content .= '"version":'.$rs_vj->versione.',';
			$json_content .= '"stores":[';
			$vir = '';
		while($rs = mysql_fetch_object($result)){

			/////////////////////////////////////////////////////
			// DATI FORMATATI
			$rag_soc =		fix_text_json($rs->rag_soc);
			$indirizzo =	fix_text_json($rs->indirizzo);
			$cap =			fix_text_json($rs->cap);
			$localita =		fix_text_json($rs->localita);
			$telefono =		fix_text_json($rs->telefono);
			$email =		fix_text_json($rs->email);
			$latudine =		($rs->geocoding_lat != '') ? $rs->geocoding_lat : 'null';
			$longitudine =	($rs->geocoding_lng != '') ? $rs->geocoding_lng : 'null';
			/////////////////////////////////////////////////////

			$json_content .= $vir; // Eventuale aggiunta della virgola
			$json_content .= '{';
				$json_content .= '"name":"'.$rag_soc.'",';
				$json_content .= '"address":"'.$indirizzo.'",';
				$json_content .= '"cap":"'.$cap.'",';
				$json_content .= '"city":"'.$localita.'",';
				$json_content .= '"state":"",';
