				$json_content .= '"phone":"'.$telefono.'",';
				$json_content .= '"email":"'.$email.'",';
				$json_content .= '"latitude":'.$latudine.',';
				$json_content .= '"longitude":'.$longitudine;
			$json_content .= '}';
			$vir = ','; // Impostazione virgola dopo il primo ciclo

		}
			$json_content .= ']';
		$json_content .= '}';

	}

	// Codifica UTF8
	$json_content =				utf8_encode($json_content);
	$json_content_versione =	utf8_encode($json_content_versione);

	// Creazione JSON (versione)
	$filename_1 = 'stores_check.json';
	$path_file_1 = $_SERVER['DOCUMENT_ROOT'].'/mobile/'.$filename_1;
