//============== Cancellazione files ====================
function cancella_file($file, $chiave_funzione = ''){

	global $panel_info_;
	$array_canc = array('');
	$response = true; // dafult

	if (!empty($chiave_funzione)) {$array_canc = $panel_info_['prefix_img'][$chiave_funzione];} 

	foreach($array_canc as $tipo){
		$file_del = str_replace(basename($file), $tipo.basename($file), $file);		

		if(is_file($file_del)){

			if($_SERVER['DOCUMENT_ROOT'] == 'C:\Inetpub\Prova'){$file_del = str_replace('/', '\\', $file_del);}

			if(!@unlink($file_del)){
				## Gestione errori ##
				//avviso_admin('[DELETE FILE]<br />Errore file non cancellato<br />'.$file_del);
				log_errore_canc($file_del);
				$response = false;
			} 
		}
		unset($file_del);

	}

	return $response;

}

function log_errore_canc($file_del) {
	global $db;
	$sql = "INSERT INTO log_errore_canc (file, data) VALUES ('".fixstr($file_del)."', NOW())";
	@mysql_query($sql, $db);
}

// Cancellazione cartelle e file
function cancella_cartella($dir){
	$handle = opendir($dir);
	while (false!==($FolderOrFile = readdir($handle))){
		if($FolderOrFile != "." && $FolderOrFile != ".."){
			if(is_dir("$dir/$FolderOrFile")){cancella_cartella("$dir/$FolderOrFile");}else{unlink("$dir/$FolderOrFile");}
		}
	}
	closedir($handle);
	if(rmdir($dir)){$success = true;}
	return $success;
} 
