$mysql["password"]=getenv("DB_PASSWORD");
$mysql["database"]=getenv("DB_DATABASE");
$mysql["charset"]=getenv("DB_CHARSET")?:"utf8";
echo "admin DB -> host={$mysql["host"]} user={$mysql["user"]} db={$mysql["database"]} charset={$mysql["charset"]} pass=".strlen($mysql["password"])."chars\n";
try { new PDO("mysql:host={$mysql["host"]};dbname={$mysql["database"]}", $mysql["user"], $mysql["password"]); echo "PDO connect OK\n"; }
catch(Exception $e){ echo "PDO: ".$e->getMessage()."\n"; }
' 2>&1

